  `TGL_MTS` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `TGL_AKTIF` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `TGL_JA` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  PRIMARY KEY (`NO_AGT`),
  KEY `fk_anggota_1` (`ID_KS`),
  KEY `fk_anggota_2` (`ID_KS_ASL`),
  CONSTRAINT `FK_ANGGOTA_1` FOREIGN KEY (`ID_KS`) REFERENCES `kel_sah` (`ID_KEL`),
  CONSTRAINT `FK_ANGGOTA_2` FOREIGN KEY (`ID_KS_ASL`) REFERENCES `kel_sah` (`ID_KEL`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
